esbmc_test_source:
contract InvMutTest {
    C c;
    address creatorAddress;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We pass a target address to which migrateTo will attempt to send funds.
    // No Ether is sent with this call. We avoid calling deposit/refund/withdraw to prevent triggering deposit asserts.
    function run(address to) public payable {
        require(to != address(0), "nonzero target");

        uint256 beforeBalance = address(c).balance;

        // Attempt migrateTo and observe whether it reverts
        bool didRevert;
        c.migrateTo(to); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        uint256 afterBalance = address(c).balance;

        // General rule:
        // - If migrateTo reverted, the contract balance must be unchanged.
        // - If migrateTo succeeded, the contract balance must become zero (drained).
        // Additionally, only the creator can make migrateTo succeed: since calls from this test are from the test contract,
        // if creatorAddress != address(this) then the call must have reverted; if creatorAddress == address(this) it may succeed.
        assert(
            (didRevert && afterBalance == beforeBalance)
            || (!didRevert && afterBalance == 0)
        );
    }

    receive() external payable {}
}

